SELECT l.labsampnum,c.result_source_key,c.prep_code,cnn.pedon_key,cnn.site_key,p.pedlabsampnum,l.hzn_top,l.hzn_bot,l.hzn_desgn,cnn.upedonid,cnn.site_obsdate,cnn.latitude_decimal_degrees,cnn.longitude_decimal_degrees,s.area_name AS state_name,ct.area_name AS county_name,ph_saturated_paste,electrical_conductivity_satx,ca_satx,mg_satx,na_satx,k_satx,cl_satx,so4_satx,ph_saturated_paste_method,electrical_cond_satx_method,ca_satx_method,mg_satx_method,na_satx_method,k_satx_method,cl_satx_method,so4_satx_method,ph_water_extract_method,water_extract_method,ph_water_extract,ec_water_extract,calcium_water_extractable,magnesium_water_extractable,sodium_water_extractable,potassium_water_extractable,chloride_water_extractable,sulfate_water_extractable FROM lab_combine_nasis_ncss cnn INNER JOIN lab_pedon p ON p.pedon_key=cnn.pedon_key INNER JOIN lab_layer l ON l.pedon_key=p.pedon_key INNER JOIN lab_chemical_properties c ON c.labsampnum=l.labsampnum INNER JOIN lab_area s ON cnn.state_key=s.area_key LEFT JOIN lab_area ct ON cnn.county_key=ct.area_key WHERE s.area_code='TX'